66	// dedupeProposals collapses identical queue entries. Its identity must match
67	// factsync.ProposalID — action, candidate, target, BRANCH and PROPOSED_BY —
68	// because that is the id the shared review queue, the shared-proposal ledger and
69	// the `facts review` interlock all key on. Keying on the triple alone silently
70	// merges rows those layers treat as distinct: distill's private, unattributed
71	// backlog entry and a cross-member conflict `facts sync` raised for the same two
72	// facts collapse onto whichever landed first, and since the private one is
73	// written first the member-attributed entry is the one that disappears — so the
74	// conflict is never published to the team and the member settles locally a
75	// decision the next sync will overrule.
76	func dedupeProposals(proposals []factProposal) []factProposal {
77		seen := make(map[string]struct{}, len(proposals))
78		out := make([]factProposal, 0, len(proposals))
79		key := func(p factProposal) string {
80			return strings.Join([]string{p.Action, p.CandidateID, p.TargetID, p.Branch, p.ProposedBy}, "\x00")
81		}
