154	// reconcileInput renders the candidate and existing fact lists for stdin. Both
155	// are numbered 1-based; the agent refers to them by number, and the parser maps
156	// those numbers back to records (existing numbers resolve to fact ids).
157	func reconcileInput(candidates, existing []factRecord) []byte {
158		var b strings.Builder
159		b.WriteString("CANDIDATES\n")
160		for i, c := range candidates {
161			fmt.Fprintf(&b, "%d [%s] %s\n", i+1, strings.Join(c.Paths, ","), c.Text)
162		}
163		b.WriteString("\nEXISTING\n")
164		for i, e := range existing {
165			fmt.Fprintf(&b, "%d [%s] %s\n", i+1, strings.Join(e.Paths, ","), e.Text)
166		}
167		return []byte(b.String())
168	}
