170	// parseReconcileActions turns the agent's decision lines into factActions. Each
171	// candidate gets exactly one action: a line that is missing, malformed, or
172	// references an out-of-range existing fact degrades that candidate to `new`
173	// (with a warning) so a parser hiccup never drops a fact or misapplies a
174	// merge/supersede.
175	func parseReconcileActions(output string, candidates, existing []factRecord) ([]factAction, []string) {
176		decided := make(map[int]factAction, len(candidates))
177		var warnings []string
178	
179		for _, raw := range strings.Split(output, "\n") {
180			line := strings.TrimSpace(raw)
181			if line == "" {
182				continue
183			}
184			fields := strings.Fields(line)
185			// Need at least "<candidate#> <decision>". The canonical form is
186			// "<candidate#> <decision> <existing#-or-dash> <confidence>", but lighter
187			// models (gpt-5.3-codex-spark) drop the "-" placeholder for new
188			// ("3 new 1.0") or omit a trailing confidence; handle those per kind below
189			// instead of rejecting the whole line.
190			if len(fields) < 2 {
191				warnings = append(warnings, "reconcile: malformed line: "+truncateString(line, 80))
192				continue
193			}
194			ci, err := strconv.Atoi(fields[0])
195			if err != nil || ci < 1 || ci > len(candidates) {
196				warnings = append(warnings, "reconcile: bad candidate number: "+truncateString(line, 80))
197				continue
198			}
199			candidate := candidates[ci-1]
200			kind := strings.ToLower(fields[1])
201			switch kind {
202			case factActionNew:
203				// Tolerate a missing "-" placeholder. Confidence is the last field when
204				// it is numeric; otherwise default to 1.0 (the prompt's value for new).
205				confidence := 1.0
206				if len(fields) >= 3 {
207					if last := fields[len(fields)-1]; isNumericToken(last) {
208						confidence = parseConfidence(last)
209					}
210				}
211				decided[ci] = factAction{Kind: factActionNew, Confidence: confidence, Candidate: candidate}
212			case factActionMerge, factActionSupersede:
213				if len(fields) < 3 {
214					warnings = append(warnings, fmt.Sprintf("reconcile: %s missing existing number, treating candidate %d as new", kind, ci))
215					decided[ci] = factAction{Kind: factActionNew, Confidence: 1.0, Candidate: candidate}
216					continue
217				}
218				ei, eerr := strconv.Atoi(fields[2])
219				if eerr != nil || ei < 1 || ei > len(existing) {
220					warnings = append(warnings, fmt.Sprintf("reconcile: %s with bad existing number, treating candidate %d as new", kind, ci))
221					decided[ci] = factAction{Kind: factActionNew, Confidence: 1.0, Candidate: candidate}
222					continue
223				}
224				// A missing confidence stays 0 so the action is queued for review
225				// rather than auto-applied.
226				confidence := 0.0
227				if len(fields) >= 4 {
228					confidence = parseConfidence(fields[3])
229				}
230				decided[ci] = factAction{Kind: kind, TargetID: existing[ei-1].ID, Confidence: confidence, Candidate: candidate}
231			default:
232				warnings = append(warnings, "reconcile: unknown decision: "+truncateString(line, 80))
233			}
234		}
235	
236		actions := make([]factAction, 0, len(candidates))
237		for i, candidate := range candidates {
238			if action, ok := decided[i+1]; ok {
239				actions = append(actions, action)
240				continue
241			}
242			warnings = append(warnings, fmt.Sprintf("reconcile: no decision for candidate %d, treating as new", i+1))
243			actions = append(actions, factAction{Kind: factActionNew, Confidence: 1.0, Candidate: candidate})
244		}
245		return actions, warnings
246	}
