248	// isNumericToken reports whether a token parses as a finite float, used to tell
249	// a trailing confidence value apart from a "-" placeholder or missing field.
250	// NaN/±Inf are rejected: ParseFloat accepts them, but a NaN confidence would
251	// silently bypass the low-confidence gate downstream (every comparison with NaN
252	// is false), so they must not be treated as a numeric confidence.
253	func isNumericToken(token string) bool {
254		value, err := strconv.ParseFloat(token, 64)
255		return err == nil && !math.IsNaN(value) && !math.IsInf(value, 0)
256	}
257	
258	// parseConfidence reads a confidence token, clamped to [0,1]; unparseable
259	// values (including NaN/±Inf, which would otherwise slip past the [0,1] clamp
260	// and the auto-apply threshold) default to 0 so an unreadable confidence is
261	// treated as low and queued for review rather than auto-applied.
262	func parseConfidence(token string) float64 {
263		value, err := strconv.ParseFloat(token, 64)
264		if err != nil || math.IsNaN(value) || math.IsInf(value, 0) {
265			return 0
266		}
267		if value < 0 {
268			return 0
269		}
270		if value > 1 {
271			return 1
272		}
273		return value
274	}
