276	// activeFactsAtPaths returns the active facts whose paths intersect the given
277	// path set, most-recently-updated first, capped at maxReconcileExisting. The
278	// boolean reports whether the cap dropped any facts.
279	func activeFactsAtPaths(records []factRecord, paths []string) ([]factRecord, bool) {
280		want := make(map[string]struct{}, len(paths))
281		for _, p := range paths {
282			want[p] = struct{}{}
283		}
284		var matched []factRecord
285		for _, record := range records {
286			if record.Status != factStatusActive {
287				continue
288			}
289			for _, p := range record.Paths {
290				if _, ok := want[p]; ok {
291					matched = append(matched, record)
292					break
293				}
294			}
295		}
296		sort.SliceStable(matched, func(i, j int) bool {
297			if !matched[i].UpdatedAt.Equal(matched[j].UpdatedAt) {
298				return matched[i].UpdatedAt.After(matched[j].UpdatedAt)
299			}
300			return matched[i].ID < matched[j].ID
301		})
302		if len(matched) > maxReconcileExisting {
303			return matched[:maxReconcileExisting], true
304		}
305		return matched, false
306	}
