308	// candidatePathSet returns the sorted union of paths across the candidates.
309	func candidatePathSet(candidates []factRecord) []string {
310		seen := map[string]struct{}{}
311		for _, c := range candidates {
312			for _, p := range c.Paths {
313				seen[p] = struct{}{}
314			}
315		}
316		paths := make([]string, 0, len(seen))
317		for p := range seen {
318			paths = append(paths, p)
319		}
320		sort.Strings(paths)
321		return paths
322	}
