324	// reconcileChunkCandidates resolves a chunk's candidates against the current
325	// active set: when no existing facts share the candidates' paths, every
326	// candidate is trivially `new` (no agent call); otherwise the agent decides.
327	// An agent error falls back to treating all candidates as `new` so facts are
328	// never lost. It returns the actions to apply plus any warnings.
329	func reconcileChunkCandidates(ctx context.Context, run distillAgentRunner, agentArgs []string, candidates, active []factRecord, repoDir string, timeout time.Duration) ([]factAction, []string) {
330		existing, capped := activeFactsAtPaths(active, candidatePathSet(candidates))
331		if len(existing) == 0 {
332			actions := make([]factAction, len(candidates))
333			for i, c := range candidates {
334				actions[i] = factAction{Kind: factActionNew, Confidence: 1.0, Candidate: c}
335			}
336			return actions, nil
337		}
338		var warnings []string
339		if capped {
340			warnings = append(warnings, fmt.Sprintf("reconcile: more than %d existing facts at these paths; comparing against the %d most recent", maxReconcileExisting, maxReconcileExisting))
341		}
342		out, err := run(ctx, repoDir, agentArgs, reconcileInput(candidates, existing), timeout)
343		if err != nil {
344			warnings = append(warnings, fmt.Sprintf("reconcile agent failed, treating %d candidates as new: %v", len(candidates), err))
345			actions := make([]factAction, len(candidates))
346			for i, c := range candidates {
347				actions[i] = factAction{Kind: factActionNew, Confidence: 1.0, Candidate: c}
348			}
349			return actions, warnings
350		}
351		actions, parseWarnings := parseReconcileActions(out, candidates, existing)
352		return actions, append(warnings, parseWarnings...)
353	}
