#!/usr/bin/env python3
"""Threshold sweep for the COR-2184 reconcile prefilter.

Reads the instrumented reconcile dump (one JSON object per agent-adjudicated
call) and reports, per similarity metric and threshold:
  - positive recall: fraction of agent merge/supersede decisions whose
    candidate would still have reached the agent,
  - candidate skip rate: fraction of candidates auto-'new' without the agent,
  - call elimination: fraction of calls where no candidate crossed the
    threshold (the whole agent round-trip disappears).
"""
import json
import math
import re
import sys
from collections import Counter

TOKEN = re.compile(r"[a-z0-9]{2,}")


def tokens(text):
    return TOKEN.findall(text.lower())


def jaccard(a, b):
    sa, sb = set(a), set(b)
    if not sa or not sb:
        return 0.0
    return len(sa & sb) / len(sa | sb)


def overlap(a, b):
    sa, sb = set(a), set(b)
    if not sa or not sb:
        return 0.0
    return len(sa & sb) / min(len(sa), len(sb))


def cosine(a, b):
    ca, cb = Counter(a), Counter(b)
    dot = sum(ca[t] * cb[t] for t in ca if t in cb)
    na = math.sqrt(sum(v * v for v in ca.values()))
    nb = math.sqrt(sum(v * v for v in cb.values()))
    if na == 0 or nb == 0:
        return 0.0
    return dot / (na * nb)


METRICS = {"jaccard": jaccard, "overlap": overlap, "cosine": cosine}


def main(path):
    calls = []  # per call: list of (best_score_per_metric, is_positive, kind)
    n_calls = n_cand = n_pos = 0
    for line in open(path):
        line = line.strip()
        if not line:
            continue
        d = json.loads(line)
        existing = [(tokens(e["text"]), set(e.get("paths") or [])) for e in d["existing"]]
        if not existing:
            continue
        n_calls += 1
        rows = []
        for cand, act in zip(d["candidates"], d["actions"]):
            n_cand += 1
            ct = tokens(cand["text"])
            cp = set(cand.get("paths") or [])
            best = {m: 0.0 for m in METRICS}
            for et, ep in existing:
                # production would only compare against facts sharing a path
                # with this candidate; fall back to all when paths are empty
                if cp and ep and not (cp & ep):
                    continue
                for m, fn in METRICS.items():
                    s = fn(ct, et)
                    if s > best[m]:
                        best[m] = s
            pos = act["kind"] in ("merge", "supersede")
            if pos:
                n_pos += 1
            rows.append((best, pos, act["kind"]))
        calls.append(rows)

    print(f"calls={n_calls} candidates={n_cand} positives={n_pos} "
          f"(merge/supersede rate {n_pos / max(1, n_cand):.1%})\n")

    for m in METRICS:
        print(f"--- metric: {m} ---")
        print(f"{'thr':>5} {'pos-recall':>10} {'cand-skip':>10} {'call-elim':>10}")
        for t10 in range(5, 100, 5):
            t = t10 / 100
            kept_pos = skipped = eliminated = 0
            for rows in calls:
                any_kept = False
                for best, pos, _ in rows:
                    if best[m] >= t:
                        any_kept = True
                        if pos:
                            kept_pos += 1
                    else:
                        skipped += 1
                if not any_kept:
                    eliminated += 1
            recall = kept_pos / n_pos if n_pos else float("nan")
            print(f"{t:>5.2f} {recall:>10.1%} {skipped / max(1, n_cand):>10.1%} "
                  f"{eliminated / max(1, n_calls):>10.1%}")
        print()

    # score distribution of positives per metric, to see the floor
    for m in METRICS:
        pos_scores = sorted(best[m] for rows in calls for best, pos, _ in rows if pos)
        if pos_scores:
            lo = pos_scores[0]
            p5 = pos_scores[max(0, int(0.05 * len(pos_scores)) - 1)]
            med = pos_scores[len(pos_scores) // 2]
            print(f"{m}: positive scores min={lo:.2f} p5={p5:.2f} median={med:.2f}")


if __name__ == "__main__":
    main(sys.argv[1] if len(sys.argv) > 1 else "/tmp/ebr-2184-bench/reconcile.jsonl")

